import { useCallback, useMemo } from 'react';
import { useIntl } from 'react-intl';

import {
  BasicContainer,
  BrandAvatarList,
  ChartLegend,
  ComparisonLine,
  DataStateHandler,
  Skeleton,
  SubFilter,
  Waterfall,
} from 'components';
import {
  useCurrentPage,
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterManagement,
  useSubFilters,
} from 'hooks';
import { WaterfallConfig } from 'pages/pillars/ValueCreation/PerformanceTool/config';
import {
  VALUE_CREATION_TREND_COLORS,
  WATERFALL_COLORS,
} from 'pages/pillars/ValueCreation/PerformanceTool/constants';
import { useWaterfallDatasets } from 'pages/pillars/ValueCreation/PerformanceTool/hooks/useWaterfallDatasets/useWaterfallDatasets';
import { useWaterfallViewBySync } from 'pages/pillars/ValueCreation/PerformanceTool/hooks/useWaterfallViewBySync';
import { WaterfallSectionData } from 'pages/pillars/ValueCreation/PerformanceTool/types';

import {
  StyledChartContainer,
  StyledLegendContainer,
  StyledWaterfallContainer,
} from './WaterfallSection.styles';

interface WaterfallSectionProps {
  config: WaterfallConfig;
  title: string;
  measure?: string;
  tooltip?: string;
  data?: WaterfallSectionData;
  loading: boolean;
  error?: Error | null;
  variant?: 'large' | 'small';
  viewByDataApiKey?: string;
  viewByApiKeyPrefix?: string;
  skeletonProps?: React.ComponentProps<typeof Skeleton>;
}

export const WaterfallSection: React.FC<WaterfallSectionProps> = ({
  config,
  title,
  measure,
  tooltip,
  loading,
  error,
  data,
  variant = 'large',
  viewByDataApiKey = 'performance-tool-waterfall-options',
  viewByApiKeyPrefix = 'performance-tool-waterfall-options',
  skeletonProps = {
    height: '328px',
    width: '100%',
    length: 1,
    borderRadius: 'none',
  },
}) => {
  const { formatMessage } = useIntl();
  const { currentPage } = useCurrentPage();
  const { applied, isGlobalZone } = usePageFilterApplied(currentPage);
  const { dataFilters } = usePageFilterData(currentPage);
  const { applyDirect } = usePageFilterManagement(currentPage);
  const { activeSubFilters } = useSubFilters();
  const { legendItems, shouldShowLegend } = useWaterfallDatasets(data, variant);
  const chartData = data?.[variant];
  const contextKey = useMemo(
    () => config.getContextKey(applied, isGlobalZone),
    [config, applied, isGlobalZone],
  );

  const isViewByDisabled = useMemo(
    () => config.isViewByDisabled(contextKey, activeSubFilters, applied),
    [config, contextKey, activeSubFilters, applied],
  );

  const { handleViewByChange } = useWaterfallViewBySync({
    config,
    contextKey,
  });

  const normalizeKpiConfig = (value: string) => value.replaceAll('_', '-');

  const rightContent = useMemo(
    () => (
      <SubFilter.Select
        apiKey={`${viewByApiKeyPrefix}_${normalizeKpiConfig(config.kpiName)}`}
        dataApiKey={viewByDataApiKey}
        params={{}}
        stateKey="waterfall_view_by"
        contextKey={contextKey}
        valueLabel="View by:"
        shape="pill"
        size="medium"
        chips
        clearChips={false}
        disabled={isViewByDisabled}
        onValueChange={handleViewByChange}
      />
    ),
    [
      config.kpiName,
      contextKey,
      isViewByDisabled,
      handleViewByChange,
      viewByApiKeyPrefix,
      viewByDataApiKey,
    ],
  );

  const disabledIndexes = useMemo(() => {
    return config.getDisabledIndexes?.(chartData?.labels) ?? [];
  }, [config, chartData?.labels]);

  const handleBarClick = useCallback(
    (index: number | null) => {
      if (index === null) {
        return;
      }

      config.handleBarClick({
        index,
        labels: chartData?.labels,
        activeSubFilters,
        dataFilters,
        applied,
        applyDirect,
      });
    },
    [
      config,
      chartData?.labels,
      activeSubFilters,
      dataFilters,
      applied,
      applyDirect,
    ],
  );

  const renderLegend = useCallback(() => {
    const brandsData = chartData?.images?.data?.map((brand, index) => {
      const { mainBrand, ...rest } = brand;
      const labelEntry = chartData?.labels?.[index];
      const country = Array.isArray(labelEntry) ? labelEntry[1] : undefined;

      return {
        ...rest,
        index,
        description: country || undefined,
        ...(mainBrand?.src ? { mainBrand } : {}),
      };
    });

    return (
      <>
        {brandsData?.length ? (
          <div style={{ marginTop: 8, marginBottom: 12 }}>
            <BrandAvatarList
              data={brandsData}
              length={chartData?.labels?.length ?? brandsData.length}
              borderConfig={{ marginLeft: 16, marginRight: 16 }}
              gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
            />
          </div>
        ) : null}
      </>
    );
  }, [chartData]);

  return (
    <BasicContainer
      header={{
        title,
        measure,
        tooltip,
        titleSize: 'H4',
        rightContent,
      }}
      layout={{
        border: 'small',
        borderRadius: 'large',
        shadow: 'small',
        bodyPadding: false,
        bottomSeparator: 'border',
      }}
      fullWidth
    >
      <DataStateHandler
        loading={loading}
        error={error}
        empty={!chartData}
        message={{
          description: formatMessage({
            id: 'Common.dataUnavailable.title',
            defaultMessage: 'Data not available',
          }),
        }}
        skeletonProps={skeletonProps}
      >
        <StyledWaterfallContainer>
          <StyledChartContainer>
            {shouldShowLegend && (
              <StyledLegendContainer>
                <ChartLegend items={legendItems} />
              </StyledLegendContainer>
            )}
            <Waterfall
              values={chartData?.values || []}
              labels={chartData?.labels || []}
              formattedData={chartData?.formattedData}
              showLabels={false}
              options={{
                animation: false,
              }}
              colors={WATERFALL_COLORS}
              interactiveConfig={{
                onBarSelect: handleBarClick,
                clickability: {
                  enabled: true,
                  disabledIndexes,
                },
                renderLegend,
                fillHeight: true,
                showTooltip: true,
              }}
              stripedIndexes={chartData?.stripedIndexes || []}
            />
          </StyledChartContainer>
          {chartData?.comparisonLine?.data && (
            <div style={{ marginTop: 12 }}>
              <ComparisonLine
                data={chartData?.comparisonLine?.data}
                gridColumnsLength={chartData.labels?.length}
                borderConfig={{ marginLeft: 16, marginRight: 16 }}
                gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
                trendColors={VALUE_CREATION_TREND_COLORS}
              />
            </div>
          )}
        </StyledWaterfallContainer>
      </DataStateHandler>
    </BasicContainer>
  );
};
